const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin });
let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line.trim());
});
rl.on('close', () => {
    const n = parseInt(inputLines[0], 10);
    const result = new Set();

    for (let x = 0; x <= 9; x++) {
        for (let y = x; y <= 9; y++) {
            for (let len = 1; len <= 10; len++) {
                // generate all combinations of digits x,y of length len
                const total = 1 << len;
                for (let mask = 0; mask < total; mask++) {
                    let digits = [];
                    for (let i = 0; i < len; i++) {
                        const bit = (mask >> i) & 1;
                        digits.push(bit === 0 ? x : y);
                    }
                    if (digits[0] === 0) continue; // no leading zero
                    let numStr = digits.join('');
                    let num = parseInt(numStr, 10);
                    if (num <= n) {
                        result.add(num);
                    }
                }
            }
        }
    }

    console.log(result.size);
});
